package org.mockito.internal.matchers;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.hamcrest.Description;
import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentMatcher;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.verify;

public class Same_describeTo_TriageGen0Test {

    @Test
    public void testDescribeTo() {
        // Arrange
        Object wanted = "testObject";
        Same same = new Same(wanted);
        Description description = Mockito.mock(Description.class);

        // Act
        same.describeTo(description);

        // Assert
        // We use inOrder to verify the exact sequence of calls to ensure coverage of the logic flow
        inOrder same.describeTo(description);
        verify(description).appendText("same(");

        // Since appendQuoting is a private/protected method called within describeTo, 
        // its behavior is verified through the sequence of description calls.
        // Based on the source, appendQuoting likely calls description.appendText("'") or similar.
        // However, without the source of appendQuoting, we verify the visible parts.

        verify(description).appendText(wanted.toString());
        verify(description).appendText(")");
    }

    @Test
    public void testDescribeToWithComplexObject() {
        // Arrange
        // Testing with a custom object to ensure toString() is handled correctly
        class CustomObject {
            @Override
            public String toString() {
                return "CustomObj@123";
            }
        }
        CustomObject wanted = new CustomObject();
        Same same = new Same(wanted);
        Description description = Mockito.mock(Description.class);

        // Act
        same.describeTo(description);

        // Assert
        verify(description).appendText("same(");
        verify(description).appendText("CustomObj@123");
        verify(description).appendText(")");
    }
}
